'use strict';
let composerImages=[],postSubmitting=false,postCooldownTimer=null,composerGeneration=0;
function postCooldownSeconds(){const deadline=Number(read('altmoa-post-cooldown:'+session?.user?.id,0));return Number.isFinite(deadline)?Math.max(0,Math.ceil((deadline-Date.now())/1000)):0;}
function renderPostSubmit(){const button=$('writesubmit');if(!button||!button.isConnected){if(postCooldownTimer!==null)clearInterval(postCooldownTimer);postCooldownTimer=null;return;}const left=postCooldownSeconds();button.disabled=postSubmitting||left>0;button.textContent=postSubmitting?'등록 중…':left>0?left+'초 후 등록 가능':'게시글 등록';if(!left&&postCooldownTimer!==null){clearInterval(postCooldownTimer);postCooldownTimer=null;}}
function watchPostCooldown(){renderPostSubmit();if(postCooldownSeconds()>0&&postCooldownTimer===null)postCooldownTimer=setInterval(renderPostSubmit,1000);}
function rememberPostCooldown(userId=session?.user?.id){if(userId)store('altmoa-post-cooldown:'+userId,Date.now()+60000);watchPostCooldown();}

function parseTags(value){const tags=[...new Set(String(value||'').normalize('NFKC').split(/[\s,]+/).map(t=>t.replace(/^#+/,'').toUpperCase()).filter(Boolean))];if(!tags.length||tags.length>10||tags.some(t=>!/^[A-Z0-9가-힣_]{1,20}$/.test(t)))throw Error('태그는 1~10개, 각 20자 이내의 한글·영문·숫자로 입력하세요.');return tags;}
function renderTags(tags){return (tags||[]).filter(t=>/^[A-Z0-9가-힣_]{1,20}$/i.test(t)).map(t=>'<span class="post-tag">#'+escapeHTML(t)+'</span>').join('');}
async function preparePhoto(file){
 if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10485760)throw Error('사진은 JPG·PNG·WebP, 원본 10MB 이하만 가능합니다.');
 const bitmap=await createImageBitmap(file);try{if(bitmap.width*bitmap.height>40000000)throw Error('사진 해상도가 너무 큽니다.');const scale=Math.min(1,1600/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.85));if(!blob||blob.size>2097152)throw Error('사진을 2MB 이하로 줄여주세요.');return blob;}finally{bitmap.close();}
}
function renderComposerImages(){
 $('photopreviews').innerHTML=composerImages.map((image,i)=>'<div class="photo-preview"><img src="'+image.preview+'" alt="첨부 사진 '+(i+1)+'"><button type="button" onclick="removeComposerImage('+i+')">삭제</button></div>').join('');
}
function resetComposer(){composerGeneration++;composerImages.forEach(image=>URL.revokeObjectURL(image.preview));composerImages=[];if(postCooldownTimer!==null)clearInterval(postCooldownTimer);postCooldownTimer=null;}
function removeComposerImage(index){if(postSubmitting||!Number.isInteger(index)||!composerImages[index])return;URL.revokeObjectURL(composerImages[index].preview);composerImages.splice(index,1);renderComposerImages();}
async function selectPhotos(files){if(postSubmitting||activeView!=='write')return;const generation=composerGeneration,input=$('postphotos');if(input.disabled)return;input.disabled=true;try{if(composerImages.length+files.length>3)throw Error('사진은 최대 3장 첨부할 수 있어요.');for(const file of files){const blob=await preparePhoto(file);if(generation!==composerGeneration||activeView!=='write')return;composerImages.push({blob,preview:URL.createObjectURL(blob)});}renderComposerImages();}catch(error){if(generation===composerGeneration&&activeView==='write'&&$('writeerror'))$('writeerror').textContent=error.message;}finally{if(generation===composerGeneration){input.value='';input.disabled=false;}}}
async function storageRequest(path,options={}){const token=await freshToken();return fetchJSON(config.supabaseUrl+'/storage/v1/'+path,{...options,headers:{apikey:config.supabaseKey,...(token?{Authorization:'Bearer '+token}:{}),...options.headers}});}
async function deleteUploadedPhotos(paths){if(!paths.length)return;try{await storageRequest('object/post-images',{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify({prefixes:paths})});}catch{toast('첨부 정리에 실패했어요. 문의로 알려주세요.');}}
async function uploadComposerImages(authorId=session?.user?.id){const images=[...composerImages],paths=[];try{for(const image of images){if(session?.user?.id!==authorId)throw Error('로그인 계정이 변경되었습니다.');const path=authorId+'/'+crypto.randomUUID()+'.jpg';await storageRequest('object/post-images/'+path,{method:'POST',headers:{'Content-Type':'image/jpeg'},body:image.blob});paths.push(path);}return paths;}catch(error){await deleteUploadedPhotos(paths);throw error;}}
async function loadPostPhotos(paths,id){
 const request=postPageRequest;
 if(!paths?.length)return;const target=$('postphotosview');if(!target)return;
 const results=await Promise.allSettled(paths.slice(0,3).map(async path=>{if(!/^[a-f0-9-]{36}\/[a-f0-9-]{36}\.jpg$/.test(path))throw Error('invalid_path');const {data}=await storageRequest('object/sign/post-images/'+path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({expiresIn:60})});const signed=data.signedURL||data.signedUrl;if(!signed?.startsWith('/object/sign/post-images/'))throw Error('invalid_url');return config.supabaseUrl+'/storage/v1'+signed;}));
 if(activePostId!==id||request!==postPageRequest||!$('postphotosview'))return;target.innerHTML=results.map((r,i)=>r.status==='fulfilled'?'<a href="'+escapeHTML(r.value)+'" target="_blank" rel="noopener"><img src="'+escapeHTML(r.value)+'" alt="게시글 첨부 사진 '+(i+1)+'" loading="lazy" referrerpolicy="no-referrer"></a>':'<p class="subtle">사진을 불러오지 못했어요. 글을 다시 열어주세요.</p>').join('');
}
async function loadPoll(post){
 const request=postPageRequest,id=post.id;if(!post.poll_options?.length||activePostId!==id)return;
 try{const [{data:results},{data:mine}]=await Promise.all([db('rpc/poll_results',{method:'POST',body:JSON.stringify({p_post:id})}),session?.user?db('poll_votes?'+new URLSearchParams({select:'option_index',post_id:'eq.'+id,user_id:'eq.'+session.user.id})):Promise.resolve({data:[]})]);if(activePostId!==id||request!==postPageRequest||!$('postpoll'))return;const total=results.reduce((n,r)=>n+Number(r.votes),0);$('postpoll').innerHTML='<h3>'+escapeHTML(post.poll_question)+'</h3><p class="subtle">1인 1표 · 총 '+total+'명 참여 · 투표 후 변경 불가</p>'+post.poll_options.map((option,i)=>{const votes=Number(results.find(r=>r.option_index===i)?.votes||0);return '<button class="poll-option" data-poll-option="'+i+'"'+(mine.length?' disabled':'')+'>'+escapeHTML(option)+'<span>'+votes+'표 · '+(total?Math.round(votes/total*100):0)+'%'+(mine[0]?.option_index===i?' · 내 선택':'')+'</span></button>';}).join('')+'<p id="pollerror" role="alert"></p>';let pollBusy=false;document.querySelectorAll('[data-poll-option]').forEach(button=>button.onclick=async()=>{if(pollBusy||activePostId!==id||request!==postPageRequest)return;if(!session?.user)return authModal();pollBusy=true;document.querySelectorAll('[data-poll-option]').forEach(b=>b.disabled=true);try{await db('poll_votes',{method:'POST',body:JSON.stringify({post_id:id,user_id:session.user.id,option_index:Number(button.dataset.pollOption)})});if(activePostId===id&&request===postPageRequest)await loadPoll(post);}catch(error){if(activePostId===id&&request===postPageRequest&&$('pollerror'))$('pollerror').textContent=error.status===409?'이미 참여한 투표입니다.':errorMessage(error);if(activePostId===id&&request===postPageRequest)document.querySelectorAll('[data-poll-option]').forEach(b=>b.disabled=false);}finally{pollBusy=false;}});}catch{if(activePostId===id&&request===postPageRequest&&$('postpoll'))$('postpoll').textContent='투표를 불러오지 못했어요.';}
}
